import{z as s,x as n,o,c as l,q as r,j as m,D as e,d as i,s as E,S as p}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"Performer / FAVOR+","description":"","frontmatter":{"title":"Performer / FAVOR+","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/performer-favor.md","filePath":"llm/performer-favor.md","lastUpdated":1791063341000}'),A={name:"llm/performer-favor.md"};function h(B,a,f,d,x,_){const t=n("Mermaid");return o(),l("div",null,[a[2]||(a[2]=r('<h1 id="performer-favor" tabindex="-1">Performer / FAVOR+ <a class="header-anchor" href="#performer-favor" aria-label="Permalink to &quot;Performer / FAVOR+&quot;">​</a></h1><div class="epigraph"><p>用正的正交随机特征去逼近 softmax 核，注意力就可以在线性时间内计算，同时尽量保住原来的相似度。</p><footer>—— Krzysztof Choromanski 等, Rethinking Attention with Performers, 2021</footer></div><p><a href="/llm/linear-attention">Linear Attention</a> 已经说明：只要 \\(\\mathrm{sim}(q,k)=\\phi(q)^\\top\\phi(k)\\)，计算就可以对长度线性。Katharopoulos 的 \\(\\phi\\) 是确定的，并不逼近 \\(\\exp(q^\\top k)\\)。Choromanski 等人 2021 年的 Performer 把 \\(\\phi\\) 换成随机特征，使内积在期望上等于 softmax 核；FAVOR+（Fast Attention Via Positive Orthogonal Random Features）是其中稳定、可训练的一套特征。本篇只谈这条「随机特征逼近 softmax」的机制，不把所有线性变体打包进来，也不把稀疏图当作同类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>希望保留 softmax 的尖峰——因为拷贝与检索依赖它——又希望不要物化 \\(QK^\\top\\)。随机傅里叶特征能逼近平移不变核，但对 softmax 核会出现负分量，注意力权重再归一化时可能翻号、方差爆炸。训练中的 Transformer 对这种噪声很敏感：一层抖，残差会把抖传到整网。需要的是：正值特征，使近似权重可解释为非负质量；低方差，使有限 \\(m\\) 个特征就够用；以及与因果扫描兼容，以便自回归。</p><p>Performer 把目标写成对核的蒙特卡洛：</p> \\[\\exp(q^\\top k)\\approx \\mathbb{E}_\\omega\\big[\\phi_\\omega(q)^\\top\\phi_\\omega(k)\\big] \\]<p>有限 \\(m\\) 维 \\(\\phi\\) 代入线性注意力的结合律，得到 \\(\\Theta(n m d)\\) 量级算法。\\(m\\) 是精度旋钮：太小，近似偏向平滑，尖峰变钝；太大，线性优势被特征维吃掉。</p><p><span class="marginnote">术语翻译：「核」就是给一对 \\((q,k)\\) 打相似度分的函数。softmax 核 \\(\\exp(q^\\top k)\\) 的麻烦在于要把 \\(n\\times n\\) 对全算出来；随机特征的思路是找一组 \\(\\phi\\)，让 \\(\\phi(q)\\) 与 \\(\\phi(k)\\) 的普通内积「平均而言」等于这个分数——于是每一对只需一次点积，不必物化整张表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="随机特征逼近-softmax" tabindex="-1">随机特征逼近 softmax <a class="header-anchor" href="#随机特征逼近-softmax" aria-label="Permalink to &quot;随机特征逼近 softmax&quot;">​</a></h3><p>FAVOR+ 构造正特征。直观做法是对高斯方向 \\(\\omega\\) 取 \\(\\exp(\\omega^\\top x)\\) 一类映射，再乘上 \\(\\exp(-\\|x\\|^2/2)\\) 的修正，使 \\(\\mathbb{E}[\\phi(q)^\\top\\phi(k)]=\\exp(q^\\top k)\\)（尺度可并进 \\(1/\\sqrt{d}\\)）。正值保证 \\(\\phi(q)^\\top\\phi(k)\\ge 0\\)，分母求和不会正负相消。与普通随机傅里叶相比，这是专门为注意力核改的。得到 \\(\\phi(Q),\\phi(K)\\) 后，算法与线性注意力相同：累加 \\(\\sum \\phi(k_j)v_j^\\top\\) 再与 \\(\\phi(q)\\) 相乘。</p><p><span class="marginnote">无偏是对核值而言，不是对 softmax 行向量而言。先逼近 \\(\\exp(q^\\top k)\\) 再按行归一化，归一化是非线性，有限 \\(m\\) 下权重仍有偏。实践中我们接受这一点，靠 \\(m\\) 和正交化把误差压到训练能吞的范围。</span></p><h3 id="正交化如何降方差" tabindex="-1">正交化如何降方差 <a class="header-anchor" href="#正交化如何降方差" aria-label="Permalink to &quot;正交化如何降方差&quot;">​</a></h3><p>独立采样的 \\(\\omega\\) 在有限 \\(m\\) 下方差大，不同头、不同层的近似质量不齐。FAVOR+ 用正交随机特征：先抽一组高斯向量，再 QR 正交，使方向在球面上更均匀。这不改变期望（在适当缩放后），但降低核估计的方差，于是较小的 \\(m\\) 就能稳住注意力图。训练时可把 \\(\\omega\\) 固定（像一组冻结的投影），也可偶尔重采；固定更利于复现，重采带一点正则，但生成时必须与训练一致。</p>',15)),(o(),m(p,null,{default:e(()=>[E(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%9F%A5%E8%AF%A2%E4%B8%8E%E9%94%AE%22%5D%20--%3E%20B%5B%22%E6%AD%A3%E9%9A%8F%E6%9C%BA%E7%89%B9%E5%BE%81%20phi%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%AD%A3%E4%BA%A4%E6%96%B9%E5%90%91%E9%99%8D%E6%96%B9%E5%B7%AE%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%BA%BF%E6%80%A7%E7%B4%AF%E5%8A%A0%E9%94%AE%E5%80%BC%E7%8A%B6%E6%80%81%22%5D%0A%20%20D%20--%3E%20E%5B%22%E8%BF%91%E4%BC%BC%20softmax%20%E8%AF%BB%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>因果版本与 Katharopoulos 相同，只是 \\(\\phi\\) 变成随机的。前缀状态 \\(S_t\\) 对 \\(\\omega\\) 敏感：若推理时换了一组特征，状态空间整个错位。部署必须固化 \\(\\omega\\)，把它当作架构参数，而不是每次请求重抽的噪声。</p><p><span class="marginnote">数字实例：头维 \\(d=64\\)、特征数 \\(m=64\\) 时，因果扫描的状态只有 \\(m\\times d=4096\\) 个数；而 \\(n=32768\\) 的 KV 列表要存 \\(32768\\times 64\\) 量级，是它的数百倍。省下的是显存与长度上的二次项，付出的是把精确 softmax 换成带近似误差的版本。</span></p><h3 id="正值特征与训练稳定" tabindex="-1">正值特征与训练稳定 <a class="header-anchor" href="#正值特征与训练稳定" aria-label="Permalink to &quot;正值特征与训练稳定&quot;">​</a></h3><p>负特征会让近似核出现负「权重」，softmax 的概率解释坏掉，梯度也怪。正特征把近似留在正象限，损失曲面更接近原 Transformer。即便如此，早期训练仍可能出现分母过小（特征碰巧都小）或过大（长序列累加）。对策包括：对 \\(\\phi\\) 输出做缩放、在分母加 \\(\\varepsilon\\)、与残差和 Pre-LN 搭配、对注意力输出再归一。Choromanski 等人在编码器与自回归设定下都给出了可训练证据；后来的经验是，中等长度、对尖峰不极端的任务上 Performer 接近稠密，极端检索仍落后于真 softmax。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计算路径是「随机投影 → 逐点非线性 → 线性注意力扫描」。误差来源拆两项：核估计误差 \\(\\|\\phi(q)^\\top\\phi(k)-\\exp(q^\\top k)\\|\\)，以及归一化引起的权重误差。正交化主要减第一项的方差；\\(m\\) 同时减两项。因为扫描是确定性的给定 \\(\\phi\\)，训练仍可反向到 \\(Q,K,V\\)；\\(\\omega\\) 若冻结则不接收梯度，若可学习就变成另一组投影，不再保证无偏，一般不这么做。</p>',6)),(o(),m(p,null,{default:e(()=>[E(t,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E6%A0%B8%E4%BC%B0%E8%AE%A1%E8%AF%AF%E5%B7%AE%EF%BC%9Aphi%20%E7%82%B9%E7%A7%AF%20vs%20exp(qk)%22%5D%20--%3E%20O%5B%22%E6%AD%A3%E4%BA%A4%E5%8C%96%E4%B8%BB%E8%A6%81%E5%8E%8B%E5%AE%83%E7%9A%84%E6%96%B9%E5%B7%AE%22%5D%0A%20%20M%5B%22%E5%A2%9E%E5%A4%A7%E7%89%B9%E5%BE%81%E6%95%B0%20m%22%5D%20--%3E%20O%0A%20%20K%20--%3E%20N%5B%22%E5%BD%92%E4%B8%80%E5%8C%96%E6%9D%83%E9%87%8D%E8%AF%AF%E5%B7%AE%EF%BC%9A%E5%85%88%E8%BF%91%E4%BC%BC%E5%86%8D%E5%81%9A%E9%99%A4%E6%B3%95%22%5D%0A%20%20N%20--%3E%20M2%5B%22%E8%BF%99%E4%B8%80%E9%A1%B9%E5%9F%BA%E6%9C%AC%E5%8F%AA%E8%83%BD%E9%9D%A0%20m%20%E5%8E%8B%22%5D%0A%20%20RS%5B%22omega%20%E5%9C%A8%E9%83%A8%E7%BD%B2%E6%97%B6%E8%A2%AB%E9%87%8D%E9%87%87%E6%A0%B7%22%5D%20--%3E%20MIS%5B%22%E5%9B%A0%E6%9E%9C%E7%8A%B6%E6%80%81%E9%94%99%E4%BD%8D%EF%BC%9A%E8%AE%AD%E7%BB%83%E4%B8%8E%E6%8E%A8%E7%90%86%E5%AF%B9%E4%B8%8D%E4%B8%8A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">直觉类比：\\(m\\) 个随机特征像用 \\(m\\) 次随机测量去估计两幅图像的相似度——测量越多估计越稳，但永远是估计。正交化相当于把测量角度尽量错开，同样次数测得更准；而负值特征像某次测量给出「负相似度」，物理上说不通，还会污染归一化的分母。</span></p><p>与稀疏 softmax 的对比：稀疏是精确 softmax 定义在子集上，尖峰仍硬，只是有的键不在子集里。Performer 是全部键都参与，但通过平滑核，尖峰变软。失败模式不同：稀疏会「完全看不见那根针」，Performer 会「看见但分不出针与干草」。评测应分开设计。<span class="marginnote">同一条针测曲线不能既用来骂稀疏又用来骂 Performer。前者的错误是召回为零，后者的错误是精度被背景键稀释。改 \\(m\\) 只缓解第二种；第一种只能改可见集。</span></p><p>\\(m\\) 个特征可以看成在随机方向上对核做蒙特卡洛积分。正交化之后，这些方向更像一组确定的低差异点集，方差随 \\(m\\) 下降得更快。实践中 \\(m\\) 取与头维同阶往往是起点：再小，近似偏向均匀核；再大，扫描的状态矩阵开始比分块 softmax 更贵。编码器可以双向累加两套状态（左到右、右到左），解码器只能单向，因此同样 \\(m\\) 在生成任务上更吃精度，也更怕 \\(\\omega\\) 在部署时被悄悄重采样。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(m\\) 的选择必须在目标 \\(n\\) 上画延迟–质量曲线。短序列上 Flash softmax 极快，Performer 没有必要。超长序列上，若任务是分类或平滑汇总，Performer 很合适；若任务是单点精确引用，应保留至少一层真 softmax，或改用可学习稀疏。随机特征与 RoPE 的复合要小心：先旋转再映射，\\(\\omega\\) 是在旋转后的空间里采样的，外推位置上核近似误差会变，可能被误诊为位置编码失败。</p><p>工程上，\\(\\phi\\) 的指数非线性容易在混合精度下溢出，应对 \\(q,k\\) 先按 \\(1/\\sqrt{d}\\) 缩放再进特征，并在 BF16 上对累加用 FP32。因果扫描的状态是 \\(m\\times d\\)，比 KV 列表小，但 \\(m\\) 到 256、头数再多时，状态更新也可能打满带宽。不要假设「线性 = 一定省显存」而不测量。<span class="marginnote">把 Performer 当成「免费的 softmax」会失望。它买的是可调的核近似误差对二次代价。误差预算要用针测与复制任务单独报，不能只看语言建模损失。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FAVOR+ 用正正交随机特征逼近 softmax 核，再套线性注意力的结合律。</li><li>正值避免负权重；正交化降低有限 \\(m\\) 下的方差，使特征维不必过大。</li><li>无偏针对核值，归一化后的注意力仍有偏，尖峰弱于真 softmax。</li><li>\\(\\omega\\) 必须在训练与推理间冻结，否则因果状态错位。</li><li>短序列与极端检索不是主场；平滑长程与编码器文档更合适。</li><li>与确定特征线性注意力相比，Performer 更接近 softmax，也更挑数值与 \\(m\\)。</li><li>出处：Choromanski et al., <em>Rethinking Attention with Performers</em>, ICLR 2021；对照 Katharopoulos et al., Linear Attention, 2020。</li></ul>',8))])}const D=s(A,[["render",h]]);export{k as __pageData,D as default};
